"""Handwritten independent evidence test, NOT generated by an LLM."""
import json
from pathlib import Path
import pytest
from tool_adapter import invoke_tool


@pytest.mark.contract(parameters=["date", "store"], returns=["success", "synced_count", "errors"], permission="allowed")
def test_return_types_match_contract():
    schema = json.loads((Path(__file__).resolve().parents[2] / "input/tool_def.json").read_text(encoding="utf-8"))
    result = invoke_tool("sync_inventory", {"date": "0101", "store": "us"}, ["inventory:write"])
    types = {"boolean": bool, "integer": int, "array": list}
    for field, expected in schema["returns"].items():
        assert type(result[field]) is types[expected], (
            f"CONTRACT_RETURN_MISMATCH field={field} expected={expected} "
            f"actual={result[field]!r} actual_type={type(result[field]).__name__}"
        )


@pytest.mark.contract(permission="denied")
def test_no_permission():
    with pytest.raises(PermissionError):
        invoke_tool("sync_inventory", {"date": "0101", "store": "us"}, [])


@pytest.mark.contract(parameters=["date", "store"])
@pytest.mark.parametrize("params,error", [
    ({"date": 101, "store": "us"}, TypeError),
    ({"date": "0101", "store": 1}, TypeError),
    ({"store": "us"}, ValueError),
    ({"date": "0101"}, ValueError),
    ({"date": "1332", "store": "us"}, ValueError),
    ({"date": "0101", "store": "xx"}, ValueError),
])
def test_invalid(params, error):
    with pytest.raises(error):
        invoke_tool("sync_inventory", params, ["inventory:write"])
